import { getData, hasData } from '../core/data';
import { esc } from './base';

interface Link { label: string; url: string; short?: string; note?: string }

/**
 * <pdac-qr-panel data-link="quiz1"> shows public/qr/quiz1.svg and the short
 * link from src/data/links.json. QR images are generated locally before each run
 * (npm run qr); nothing is generated by a remote service.
 */
export class PdacQrPanel extends HTMLElement {
  connectedCallback(): void {
    if (this.dataset.done) return;
    this.dataset.done = '1';
    this.classList.add('pdac-c');
    const key = this.dataset.link ?? '';
    const links = hasData('links.json') ? getData<Record<string, Link>>('links.json') : {};
    const link = links[key];
    if (!link || !link.url) {
      this.innerHTML = `<div class="qr-missing" role="note">
          <b>Link not set for “${esc(key)}”.</b>
          Add the form link to <code>src/data/links.json</code>, run <code>npm run qr</code>, then rebuild.
        </div>`;
      return;
    }
    const shown = link.short || link.url.replace(/^https?:\/\//, '');
    this.innerHTML = `
      <figure class="qr-fig">
        <img class="qr-img" src="qr/${esc(key)}.svg" alt="QR code for ${esc(link.label)}" width="420" height="420">
        <figcaption>
          <span class="qr-label">${esc(link.label)}</span>
          <span class="qr-short">${esc(shown)}</span>
          ${link.note ? `<span class="qr-note">${esc(link.note)}</span>` : ''}
        </figcaption>
      </figure>`;
    this.querySelector('img')!.addEventListener('error', () => {
      this.querySelector('.qr-img')!.replaceWith(Object.assign(document.createElement('p'), {
        className: 'qr-missing',
        textContent: 'QR image not generated yet: run npm run qr, then rebuild.',
      }));
    }, { once: true });
  }
}
